//! A lab's generated files kept readable across an update of the launcher: a run manifest on
//! disk is the version of the Isoloom that wrote it, and the runner reads one version only. A lab
//! generated by an earlier launcher (a lab left running, or parked, across the update) has its
//! files generated again for the same target before any operation opens its manifest, so it can
//! still be stopped, parked, checked, read and handed over. Generation is deterministic: the lab's
//! spec, its instance (`.isoloom-<n>/`) and the launcher's overrides give the same files the new
//! version would have written at the lab's start.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex, PoisonError};

use isoloom_manifest::ManifestVersion;

use super::errors::{ADD_AGAIN, EARLIER_FILES};
use crate::error::{Error, Result};
use crate::runtime::lab;

/// The lock of the lab in `dir`, held while its manifest's version is read and, when it isn't this
/// build's, its files are generated again: an operation reading the manifest meanwhile (a status
/// the lab page asks for during a stop) never reads a file half written. One per lab: another
/// lab's status read never waits on this one's generation (several seconds for a large lab).
fn lab_lock(dir: &Path) -> Arc<Mutex<()>> {
    static LOCKS: Mutex<BTreeMap<PathBuf, Arc<Mutex<()>>>> = Mutex::new(BTreeMap::new());
    LOCKS.lock().unwrap_or_else(PoisonError::into_inner).entry(dir.to_path_buf()).or_default().clone()
}

/// Generates the files of the lab in `dir` for `target` again when its run manifest, `manifest`,
/// isn't the version this build reads; nothing when it is, or when there is none (no files yet)
/// or it isn't one at all (the runner says what is wrong with it).
///
/// # Errors
///
/// When the lab's files can't be generated any more (its spec gone or unreadable, or the lab no
/// longer able to run there), saying what to do.
pub(super) fn current(manifest: &Path, dir: &Path, target: lab::Target) -> Result<()> {
    let lock = lab_lock(dir);
    let _held = lock.lock().unwrap_or_else(PoisonError::into_inner);
    let Some(found) = stale_version(manifest) else { return Ok(()) };
    log::info!("{}: its run manifest is version {found}, which this version doesn't read; generating the lab's files again", manifest.display());
    lab::prepare(dir, target).map(drop).map_err(|e| Error::Invalid(format!("{EARLIER_FILES}: {e}. {ADD_AGAIN}")))
}

/// The Isoloom target whose files hold a run manifest of `target` (what the runner records of a
/// run).
pub(super) fn lab_target(target: isoloom_manifest::Target) -> lab::Target {
    use isoloom_manifest::Target as Run;
    match target {
        Run::Docker => lab::Target::Docker,
        Run::DockerVm => lab::Target::DockerVm,
        Run::Vagrant => lab::Target::Vagrant,
        Run::Proxmox => lab::Target::Proxmox,
        Run::Esxi => lab::Target::Esxi,
        Run::CloudDocker => lab::Target::CloudDocker,
        Run::CloudVm => lab::Target::CloudVm,
        Run::CloudServices => lab::Target::CloudServices,
    }
}

/// The run manifest's version, as written, when the file at `manifest` declares one this build
/// doesn't read. Only that field is read.
fn stale_version(manifest: &Path) -> Option<serde_json::Value> {
    #[derive(serde::Deserialize)]
    struct Declared {
        manifest_version: Option<serde_json::Value>,
    }
    let text = std::fs::read(manifest).ok()?;
    let found = serde_json::from_slice::<Declared>(&text).ok()?.manifest_version?;
    serde_json::from_value::<ManifestVersion>(found.clone()).is_err().then_some(found)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn only_a_declared_version_this_build_doesnt_read_is_stale() {
        let dir = std::env::temp_dir().join(format!("cyberctf-stale-{}", rand::random::<u32>()));
        std::fs::create_dir_all(&dir).unwrap();
        let file = dir.join("run.json");
        let current = serde_json::to_value(ManifestVersion).unwrap();
        let read = |text: &str| {
            std::fs::write(&file, text).unwrap();
            stale_version(&file)
        };
        assert_eq!(read(r#"{"manifest_version": 0, "generator": {"name": "isoloom"}}"#), Some(serde_json::json!(0)));
        let newer = current.as_u64().unwrap() + 1;
        assert_eq!(read(&format!(r#"{{"manifest_version": {newer}}}"#)), Some(newer.into()), "a newer launcher's, after a downgrade");
        assert_eq!(read(&format!(r#"{{"manifest_version": {current}, "target": "docker"}}"#)), None, "this build's");
        assert_eq!(read("not a manifest"), None, "not one at all: the runner says what is wrong");
        assert_eq!(read("{}"), None, "no version: the runner says what is wrong");
        assert_eq!(stale_version(&dir.join("missing.json")), None);
        std::fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn a_lab_being_generated_again_holds_up_no_other_lab() {
        // Regression: one process-wide lock served every lab, so one lab's regeneration held up
        // every other lab's status read.
        let root = std::env::temp_dir().join(format!("cyberctf-regen-{}", rand::random::<u32>()));
        let (a, b) = (root.join("a"), root.join("b"));
        let held = lab_lock(&a);
        let _a_busy = held.lock().unwrap();
        let (done, finished) = std::sync::mpsc::channel();
        let other = b.clone();
        std::thread::spawn(move || done.send(current(&other.join("run.json"), &other, lab::Target::Docker).is_ok()).unwrap());
        assert_eq!(finished.recv_timeout(std::time::Duration::from_secs(5)), Ok(true), "lab b waited on lab a");
        assert!(Arc::ptr_eq(&lab_lock(&a), &held), "one lock per lab, the same each time");
        assert!(!Arc::ptr_eq(&lab_lock(&b), &held));
    }

    #[test]
    fn a_runs_target_is_the_isoloom_target_of_the_same_name() {
        use isoloom_manifest::Target as Run;
        for run in [Run::Docker, Run::DockerVm, Run::Vagrant, Run::Proxmox, Run::Esxi, Run::CloudDocker, Run::CloudVm, Run::CloudServices] {
            assert_eq!(serde_json::to_value(lab_target(run)).unwrap(), serde_json::to_value(run).unwrap(), "{run:?}");
        }
    }
}
